// ─── Language map ─────────────────────────────────────────────────────────────

export type LangCode = 'en'|'ru'|'uk'|'de'|'fr'|'es'|'pt'|'it'|'tr'|'ar'|'hi'|'zh'|'ja'|'ko'|'vi'|'id'|'pl'|'th'|'tl'|'nl'|'sv'|'ro'|'bn';

export const LANGUAGES: { code: LangCode; label: string; flag: string; rtl?: boolean }[] = [
  { code: 'en', label: 'English',            flag: '🇺🇸' },
  { code: 'ru', label: 'Русский',            flag: '🇷🇺' },
  { code: 'uk', label: 'Українська',         flag: '🇺🇦' },
  { code: 'pl', label: 'Polski',             flag: '🇵🇱' },
  { code: 'de', label: 'Deutsch',            flag: '🇩🇪' },
  { code: 'fr', label: 'Français',           flag: '🇫🇷' },
  { code: 'es', label: 'Español',            flag: '🇪🇸' },
  { code: 'pt', label: 'Português',          flag: '🇧🇷' },
  { code: 'it', label: 'Italiano',           flag: '🇮🇹' },
  { code: 'tr', label: 'Türkçe',             flag: '🇹🇷' },
  { code: 'ar', label: 'العربية',            flag: '🇸🇦', rtl: true },
  { code: 'hi', label: 'हिन्दी',             flag: '🇮🇳' },
  { code: 'zh', label: '简体中文',            flag: '🇨🇳' },
  { code: 'ja', label: '日本語',              flag: '🇯🇵' },
  { code: 'ko', label: '한국어',              flag: '🇰🇷' },
  { code: 'vi', label: 'Tiếng Việt',         flag: '🇻🇳' },
  { code: 'id', label: 'Bahasa Indonesia',   flag: '🇮🇩' },
  { code: 'th', label: 'ไทย',               flag: '🇹🇭' },
  { code: 'tl', label: 'Filipino',           flag: '🇵🇭' },
  { code: 'bn', label: 'বাংলা',             flag: '🇧🇩' },
  { code: 'nl', label: 'Nederlands',         flag: '🇳🇱' },
  { code: 'sv', label: 'Svenska',            flag: '🇸🇪' },
  { code: 'ro', label: 'Română',             flag: '🇷🇴' },
];

// Every dictionary falls back to English for keys it doesn't define, so a
// partially-translated locale can never render undefined for a newer key.
const PARTIAL_TRANSLATIONS: Record<LangCode, Partial<Translations>> = {
  en, ru, uk, de, fr, es, pt, it, tr, ar, hi, zh, ja, ko, vi, id, pl, th, tl, nl, sv, ro, bn,
};
const TRANSLATIONS = Object.fromEntries(
  (Object.keys(PARTIAL_TRANSLATIONS) as LangCode[]).map(code => [code, { ...en, ...PARTIAL_TRANSLATIONS[code] }])
) as Record<LangCode, Translations>;

const RTL_LANGS = new Set<LangCode>(['ar']);

const STORAGE_KEY = 'workpro_lang';

function getLang(): LangCode {
  const stored = localStorage.getItem(STORAGE_KEY) as LangCode | null;
  if (stored && TRANSLATIONS[stored]) return stored;
  // Auto-detect from browser
  const nav = navigator.language.split('-')[0] as LangCode;
  if (TRANSLATIONS[nav]) return nav;
  return 'ru';
}

export function setLang(l: LangCode) {
  localStorage.setItem(STORAGE_KEY, l);
  document.documentElement.setAttribute('dir', RTL_LANGS.has(l) ? 'rtl' : 'ltr');
  // dir told the browser which way to lay the page out but never which language
  // it is reading: <html lang> stayed "en" in all 23, so a screen reader
  // announced Arabic and Thai with English phonemes.
  document.documentElement.setAttribute('lang', l);
  window.dispatchEvent(new CustomEvent('workpro:langchange'));
}

export function t(): Translations {
  return TRANSLATIONS[getLang()] || en;
}

export function currentLang(): LangCode {
  return getLang();
}

