const ERROR_RU_PREFIX: Array<[string, string]> = [
  ['Cannot refund escrow with status:', 'Нельзя вернуть эскроу со статусом:'],
  ['Escrow cannot be resolved', 'Эскроу нельзя закрыть'],
  ['Escrow is not disputed', 'Эскроу не в споре'],
];
export function translateError(msg: any): string {
  const s = typeof msg === 'string' ? msg : (msg?.message || String(msg || ''));
  if (getLang() !== 'ru' || !s) return s;
  if (ERROR_RU[s]) return ERROR_RU[s];
  for (const [pfx, ru] of ERROR_RU_PREFIX) if (s.startsWith(pfx)) return ru;
  return s;
}

export function isRTL(): boolean {
  return RTL_LANGS.has(getLang());
}

// ── Pluralization ────────────────────────────────────────────────────────────
// Slavic three-form plural: 1 работа / 2 работы / 5 работ.
function slavicPlural(n: number, one: string, few: string, many: string): string {
  const m10 = n % 10, m100 = n % 100;
  if (m10 === 1 && m100 !== 11) return one;
  if (m10 >= 2 && m10 <= 4 && (m100 < 12 || m100 > 14)) return few;
  return many;
}

export function jobsLabel(n: number): string {
  const l = getLang();
  if (l === 'ru') return slavicPlural(n, 'работа', 'работы', 'работ');
  if (l === 'uk') return slavicPlural(n, 'робота', 'роботи', 'робіт');
  if (l === 'pl') return slavicPlural(n, 'praca', 'prace', 'prac');
  if (l === 'en') return n === 1 ? 'job' : 'jobs';
  return t().jobs.toLowerCase();
}

export function connectsLabel(n: number): string {
  const l = getLang();
  if (l === 'ru') return slavicPlural(n, 'коннект', 'коннекта', 'коннектов');
  if (l === 'uk') return slavicPlural(n, 'конект', 'конекти', 'конектів');
  if (l === 'en') return n === 1 ? 'connect' : 'connects';
  return t().connects.toLowerCase();
}

/**
 * Human label for a raw status string from the database.
 *
 * This translated for ru and uk only and returned the raw value for the other
 * 21 languages, so most users saw `funded`, `in_progress` and `disputed`
 * verbatim on My Jobs, Escrow, the job page and admin. It now goes through the
 * dictionary like everything else: `st_<status>` first, then the plain key for
 * the handful of statuses that already had one (open, completed, hired, …),
 * and only then the raw value for a status nobody has translated yet.
 */
export function statusLabel(s: string): string {
  const tr = t() as Record<string, string>;
  return tr[`st_${s}`] || tr[s] || s;
}

// ── Relative time ────────────────────────────────────────────────────────────
// Home, Notifications, Chat and JobDetail each carried their own private copy
// of this, all four hardcoded in English — so a Russian or Japanese reader saw
// "5m ago" under every job card and every notification. One implementation
// now, reading the dictionary like everything else.

/** "5m ago" — used under job cards, notifications and applications. */
export function timeAgo(d?: string | null): string {
  if (!d) return '';
  const tr = t() as Record<string, string>;
  const ms = Date.now() - new Date(d).getTime();
  if (!Number.isFinite(ms)) return '';
  const m = Math.floor(ms / 60000);
  if (m < 2) return tr.justNow;
  if (m < 60) return tr.minAgo.replace('{n}', String(m));
  const h = Math.floor(m / 60);
  if (h < 24) return tr.hourAgo.replace('{n}', String(h));
  return tr.dayAgo.replace('{n}', String(Math.floor(h / 24)));
}

/** "5m" — the compact form the chat list uses beside each conversation. */
export function timeAgoShort(d?: string | null): string {
  if (!d) return '';
  const tr = t() as Record<string, string>;
  const ms = Date.now() - new Date(d).getTime();
  if (!Number.isFinite(ms)) return '';
  const m = Math.floor(ms / 60000);
  if (m < 2) return tr.tNow;
  if (m < 60) return tr.tMin.replace('{n}', String(m));
  const h = Math.floor(m / 60);
  if (h < 24) return tr.tHour.replace('{n}', String(h));
  return tr.tDay.replace('{n}', String(Math.floor(h / 24)));
}

/** Heading over a day's worth of notifications: Today / Yesterday / Mar 3. */
export function dateGroupLabel(d: string): string {
  const tr = t() as Record<string, string>;
  const date = new Date(d);
  // toLocaleDateString on an unparseable date renders the literal string
  // "Invalid Date" as the group heading — group those under today instead.
  if (Number.isNaN(date.getTime())) return tr.dateToday;
  const now = new Date();
  if (date.toDateString() === now.toDateString()) return tr.dateToday;
  if (date.toDateString() === new Date(now.getTime() - 86400000).toDateString()) return tr.dateYesterday;
  // Intl already localises this one — just point it at the chosen language
  // instead of whatever the device happens to be set to.
  return date.toLocaleDateString(getLang(), { month: 'short', day: 'numeric' });
}

// Apply direction on load
export function applyLangDir() {
  const lang = getLang();
  document.documentElement.setAttribute('dir', RTL_LANGS.has(lang) ? 'rtl' : 'ltr');
  document.documentElement.setAttribute('lang', lang);
}
